+  const label = isMobile ? "Pay" : "Pay now";
+  const help = "We charge your card when the order ships, not before: a long line that must wrap inside the block and never push the layout sideways.";
+  if (declined) {
+    return <Declined reason={declined} />;
+  }
   return (
     <Form onSubmit={submit}>

